                if vc and not vc.is_playing():
                    vc.play(discord.FFmpegPCMAudio(source=f"reject_{msg.id}.mp3", executable="./ffmpeg"))
                    while vc.is_playing():
                        await asyncio.sleep(1)
                    await vc.disconnect()
                    if os.path.exists(f"reject_{msg.id}.mp3"):
                        os.remove(f"reject_{msg.id}.mp3")

