    {"id": 840, "q": "Bombyx mori produces:", "o": ["Silk", "Lac", "Honey", "Wax"], "a": "Silk"},
    {"id": 841, "q": "Laccifer produces:", "o": ["Lac", "Silk", "Honey", "Pearl"], "a": "Lac"},
